 69	  createLeaveRequest = async (
 70	    request: FastifyRequest,
 71	    reply: FastifyReply,
 72	  ): Promise<void> => {
 73	    const parsed = createSchema.safeParse(request.body);
 74	    if (!parsed.success) {
 75	      return reply.status(400).send({
 76	        error: 'Validation Error',
 77	        details: parsed.error.issues,
 78	      });
 79	    }
 80	
 81	    const dto = {
 82	      employeeId: parsed.data.employeeId,
 83	      leavePolicyId: parsed.data.leavePolicyId,
 84	      startDate: new Date(parsed.data.startDate),
 85	      endDate: new Date(parsed.data.endDate),
 86	      reason: parsed.data.reason,
 87	    };
 88	
 89	    try {
 90	      const result = await this.leaveRequestService.create(dto);
 91	      return reply.status(201).send(result);
 92	    } catch (err: unknown) {
 93	      if (err instanceof NotFoundError) {
 94	        return reply.status(404).send({ error: err.message, code: 'NOT_FOUND', statusCode: 404 });
 95	      }
 96	      if (err instanceof ValidationError) {
 97	        return reply.status(400).send({ error: err.message, code: 'VALIDATION_ERROR', statusCode: 400 });
 98	      }
 99	      if (err instanceof ConflictError) {
100	        return reply.status(409).send({ error: err.message, code: 'CONFLICT', statusCode: 409 });
101	      }
102	      throw err;
103	    }
104	  };
